#include <bits/stdc++.h>
#define err(...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using llong = long long;
const int MAX_N = 10;
char map_grid[MAX_N][MAX_N];
int num_scientists[MAX_N][MAX_N];
int num_rescuers[MAX_N][MAX_N];
int spread_time[MAX_N][MAX_N];
const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int travel_time[MAX_N][MAX_N][MAX_N][MAX_N];
const int TOTAL_VERTICES = 2 * MAX_N * MAX_N + 2;
const int LARGE_NUMBER = 1000000000;
vector<int> network[TOTAL_VERTICES + 1];
int capacity[TOTAL_VERTICES + 1][TOTAL_VERTICES + 1];
int current_flow[TOTAL_VERTICES + 1][TOTAL_VERTICES + 1];
int dist_level[TOTAL_VERTICES + 1];
int parent_node[TOTAL_VERTICES + 1];
int next_edge[TOTAL_VERTICES + 1];

bool construct_level_graph(int source, int sink) {
    memset(dist_level, -1, sizeof(dist_level));
    dist_level[source] = 0;
    queue<int> q;
    q.push(source);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : network[u]) {
            if (capacity[u][v] - current_flow[u][v] > 0 && dist_level[v] == -1) {
                dist_level[v] = dist_level[u] + 1;
                q.push(v);
            }
        }
    }
    return dist_level[sink] != -1;
}

bool dfs_search(int u, int sink) {
    if (u == sink) return true;
    for (int& i = next_edge[u]; i < (int)network[u].size(); ++i) {
        int v = network[u][i];
        if (dist_level[v] == dist_level[u] + 1 && capacity[u][v] - current_flow[u][v] > 0 && dfs_search(v, sink)) {
            parent_node[v] = u;
            return true;
        }
    }
    return false;
}

bool find_augmenting_path(int source, int sink) {
    memset(parent_node, -1, sizeof(parent_node));
    parent_node[source] = 0;
    return dfs_search(source, sink);
}

void initialize_flow() {
    memset(capacity, 0, sizeof(capacity));
    memset(current_flow, 0, sizeof(current_flow));
}

void insert_edge(int u, int v, int cap) {
    network[u].push_back(v);
    network[v].push_back(u);
    capacity[u][v] += cap;
}

int compute_max_flow(int source, int sink) {
    int total = 0;
    while (construct_level_graph(source, sink)) {
        memset(next_edge, 0, sizeof(next_edge));
        while (find_augmenting_path(source, sink)) {
            int bottleneck = LARGE_NUMBER;
            for (int v = sink, u = parent_node[v]; v != source; v = u, u = parent_node[v]) {
                bottleneck = min(bottleneck, capacity[u][v] - current_flow[u][v]);
            }
            for (int v = sink, u = parent_node[v]; v != source; v = u, u = parent_node[v]) {
                current_flow[u][v] += bottleneck;
                current_flow[v][u] -= bottleneck;
            }
            total += bottleneck;
        }
    }
    return total;
}

int get_node_id(int size, int r, int c, bool is_right) {
    return r * size + c + (is_right ? size * size : 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    string line;
    pair<int, int> start;
    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] == 'Y') {
                map_grid[i][j] = 'Y';
            } else if (line[j] == 'Z') {
                map_grid[i][j] = 'Z';
                start = {i, j};
            } else {
                map_grid[i][j] = '.';
                num_scientists[i][j] += line[j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                num_rescuers[i][j] += line[j] - '0';
            }
        }
    }
    memset(spread_time, -1, sizeof(spread_time));
    spread_time[start.first][start.second] = 0;
    queue<pair<int, int>> q;
    q.push(start);
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dirs[k][0], ny = y + dirs[k][1];
            if (0 <= nx && nx < n && 0 <= ny && ny < n && map_grid[nx][ny] == '.' && spread_time[nx][ny] == -1) {
                spread_time[nx][ny] = spread_time[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    memset(travel_time, -1, sizeof(travel_time));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (map_grid[i][j] == '.') {
                travel_time[i][j][i][j] = 0;
                queue<pair<int, int>> bfs;
                bfs.push({i, j});
                while (!bfs.empty()) {
                    int r = bfs.front().first, c = bfs.front().second;
                    bfs.pop();
                    if (spread_time[r][c] == -1 || travel_time[i][j][r][c] < spread_time[r][c]) {
                        for (int k = 0; k < 4; ++k) {
                            int nr = r + dirs[k][0], nc = c + dirs[k][1];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n && map_grid[nr][nc] == '.' &&
                                (spread_time[nr][nc] == -1 || travel_time[i][j][r][c] + 1 <= spread_time[nr][nc]) &&
                                travel_time[i][j][nr][nc] == -1) {
                                travel_time[i][j][nr][nc] = travel_time[i][j][r][c] + 1;
                                bfs.push({nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    int source = 2 * n * n, sink = 2 * n * n + 1;
    initialize_flow();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (num_scientists[i][j]) {
                insert_edge(source, get_node_id(n, i, j, false), num_scientists[i][j]);
            }
            if (num_rescuers[i][j]) {
                insert_edge(get_node_id(n, i, j, true), sink, num_rescuers[i][j]);
            }
            for (int ri = 0; ri < n; ++ri) {
                for (int rj = 0; rj < n; ++rj) {
                    if (travel_time[i][j][ri][rj] != -1 && travel_time[i][j][ri][rj] <= t) {
                        insert_edge(get_node_id(n, i, j, false), get_node_id(n, ri, rj, true), LARGE_NUMBER);
                    }
                }
            }
        }
    }
    cout << compute_max_flow(source, sink) << endl;
    return 0;
}
